/** Captures `part` for the seller (as capture does), then releases the rest to the buyer. */
export function settle(
  c: C, escrow: Account, buyer: Account, seller: Account, house: Account, amount: number, part: number, fee: number,
): void {
  if (part <= 0 || part > amount) refuse({ kind: "BadPart" });
  capture(c, escrow, seller, house, part, fee);
  if (part < amount) release(c, escrow, buyer, amount - part);
}
EOF
cat >> escrow.test.ts <<'EOF'

test("settle", () => {
  const c = ctx({ E: 300, A: 0, B: 0, H: 0 });
  assert.equal(run(c, () => escrow.settle(c, "E", "A", "B", "H", 300, 200, 10)), "ok");
  assert.deepEqual([...c.ledger.balances], [["E", 0], ["A", 100], ["B", 190], ["H", 10]]);
  assert.deepEqual(c.audit.events.map((e) => e.kind), ["Moved", "Moved", "Captured", "Moved", "Released"]);

  const d = ctx({ E: 50, A: 0, B: 0, H: 0 });
  assert.equal(run(d, () => escrow.settle(d, "E", "A", "B", "H", 50, 50, 5)), "ok");
  assert.deepEqual(d.audit.events.map((e) => e.kind), ["Moved", "Captured"]);
  assert.equal(d.ledger.balance("A"), 0);

  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 0, 0), "BadPart");
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 101, 0), "BadPart");
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 100, 50, 60), "BadFee");
  expectRun({ E: 100, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "E", "B", "H", 100, 50, 0), "SameAccount",
    { E: 100, B: 0 });
  expectRun({ E: 120, A: 0, B: 0, H: 0 }, (c) => escrow.settle(c, "E", "A", "B", "H", 200, 100, 0), "Insufficient 80",
    { E: 120, B: 0 });
});
EOF
